    n = len(grid); g = [row[:] for row in grid]
    def cands(i, j):
        ps = [(j, i)]
        if 2 <= 31 - i <= n - 1: ps.append((31 - i, j))
        if 2 <= 31 - j <= n - 1: ps.append((i, 31 - j))
        if 2 <= 31 - i <= n - 1 and 2 <= 31 - j <= n - 1: ps.append((31 - i, 31 - j))
        return [g[a][b] for a, b in ps if g[a][b] != hole]
    changed = True
